mapper.select:
SELECT w."単語ID" AS wordId, w."見出し語" AS heading, w."読み" AS reading, w."品詞" AS partOfSpeech, w."JLPTレベル" AS jlptLevel, w."状態コード" AS stateCode FROM public."JPN_単語情報" w WHERE w."状態コード" = 'ACTIVE' AND NOT EXISTS ( SELECT 1 FROM public."JPN_AI生成履歴情報" a WHERE a."単語ID" = w."単語ID" AND a."内容種別コード" = #{contentType} AND a."状態コード" = 'SUCCEEDED' )
AND w."単語ID" IN
#{id}
ORDER BY w."単語ID" LIMIT #{limit}

mapper.insert:
INSERT INTO public."JPN_単語詳細_会話情報" (
    "詳細ID", "表示順", "場面", "手修正フラグ", "登録者アカウントID", "登録元コード"
) VALUES (
    #{detailId}, #{row.orderNo}, #{row.scene}, false, NULL, 'BATCH'
)

INSERT INTO public."JPN_単語詳細_会話行情報" (
    "会話ID", "表示順", "話者", "日本語", "中国語", "手修正フラグ",
    "登録者アカウントID", "登録元コード"
) VALUES (
    #{row.dialogId}, #{row.orderNo}, #{row.speaker}, #{row.japanese}, #{row.chinese}, false, NULL, 'BATCH'
)

mapper.select:
SELECT COALESCE(MAX(g."内容版数"), 0) + 1
  FROM public."JPN_AI生成履歴情報" g
 WHERE g."単語ID" = #{wordId}
   AND g."内容種別コード" = #{contentType}

SELECT COALESCE(a."内容版数", 1)
FROM public."JPN_AI生成履歴情報" a
WHERE a."生成ID" = #{generationId}

mapper.insert:
INSERT INTO public."JPN_AI生成履歴情報" (
    "単語ID", "内容種別コード", "状態コード", "内容版数",
    "生成件数", "失敗件数", "登録者アカウントID", "登録元コード"
)
SELECT #{wordId}, #{contentType}, 'QUEUED', #{contentVersion},
       0, 0, NULL, 'APP'
WHERE NOT EXISTS (
    SELECT 1 FROM public."JPN_AI生成履歴情報" a
    WHERE a."単語ID" = #{wordId}
      AND a."内容種別コード" = #{contentType}
      AND a."状態コード" IN ('QUEUED', 'RUNNING')
)
